def largest_prime_factor(n: int):
    import math

    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    largest_factor = -1
    # Start with the smallest prime factor
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0 and is_prime(i):
            largest_factor = i

    # If no prime factor smaller than sqrt(n) is found, check n itself
    if largest_factor == -1 and is_prime(n):
        largest_factor = n

    return largest_factor


